const amount = (value: number | null) => value === null ? '—' : new Intl.NumberFormat('fr-BE', { maximumFractionDigits: 0 }).format(value / 1000);
const euroAmount = (value: number | null) => value === null ? '—' : new Intl.NumberFormat('fr-BE', { maximumFractionDigits: 0 }).format(value);
const percent = (value: number | null, revenue: number | null) => value === null || revenue === null || revenue === 0 ? '—' : new Intl.NumberFormat('fr-BE', { style: 'percent', maximumFractionDigits: 0 }).format(value / revenue);
const values = (year2023: number | null, year2024: number | null, year2025: number | null): Values => ({ 2023: year2023, 2024: year2024, 2025: year2025 });
const account = (code: string, label: string, year2025: number, year2024: number): Detail => ({ code, label, values: values(null, year2024, year2025) });

