export function MedipostFile() {
  const {me}=useOutletContext<{me:PublicUser}>();
  const authorised=me.role==='admin'||me.analysisAccess.includes('medipost');
  const access=useQuery({queryKey:['analysed-file','medipost'],queryFn:()=>api.analysedFile('medipost'),enabled:authorised});
  const [open, setOpen] = useState<Set<string>>(new Set());
  const [percentages, setPercentages] = useState(false);
  const [view, setView] = useState<'pnl'|'balance'|'assumptions'|'analysis'>('pnl');
  const [business,setBusiness]=useState<BusinessAssumptions>({growth:{2026:.05,2027:.05,2028:.05},rentDifference:{2026:0,2027:0,2028:0},outgoingExecutiveSalary:{2026:120000,2027:120000,2028:120000},incomingExecutiveSalary:{2026:120000,2027:120000,2028:120000},companyValue:4000000,cashExtraction:800000,loanAmount:3200000,loanYears:7,loanRate:.04,workingCapitalRate:.05,capexRate:271396/12403419,rates:{'Autres produits d’exploitation':{2026:165518/12403419,2027:165518/12403419,2028:165518/12403419},'Marchandises et approvisionnements':{2026:-7553179/12403419,2027:-7553179/12403419,2028:-7553179/12403419},'Services et biens divers':{2026:-1708634/12403419,2027:-1708634/12403419,2028:-1708634/12403419},'Frais de personnel':{2026:-2336496/12403419,2027:-2336496/12403419,2028:-2336496/12403419},'Autres charges d’exploitation':{2026:-119208/12403419,2027:-119208/12403419,2028:-119208/12403419},'Amortissements et réductions de valeur':{2026:-271396/12403419,2027:-271396/12403419,2028:-271396/12403419},'Produits financiers':{2026:15019/12403419,2027:15019/12403419,2028:15019/12403419},'Impôts sur le résultat':{2026:-142705/12403419,2027:-142705/12403419,2028:-142705/12403419}}});
  if(!authorised)return <Navigate to="/sans-acces" replace/>;
  if(access.isLoading)return <div className="state">Vérification de l’accès au dossier…</div>;
  if(access.error)return <Navigate to="/sans-acces" replace/>;
  const toggle = (label: string) => setOpen(current => { const next = new Set(current); next.has(label) ? next.delete(label) : next.add(label); return next; });
  return <>
    <PageHeader title="Medipost"><p className="breadcrumb">Dossiers analysés / Medipost</p></PageHeader>
    <div className="tabs" role="tablist"><button className={view==='pnl'?'analysis-tab active':'analysis-tab'} onClick={()=>setView('pnl')}>Compte de résultat</button><button className={view==='balance'?'analysis-tab active':'analysis-tab'} onClick={()=>setView('balance')}>Bilan</button><button className={view==='assumptions'?'analysis-tab active':'analysis-tab'} onClick={()=>setView('assumptions')}>Business plan · Hypothèses</button><button className={view==='analysis'?'analysis-tab active':'analysis-tab'} onClick={()=>setView('analysis')}>Analyse du dossier</button></div>
    {view==='balance'?<MedipostBalance/>:view==='assumptions'?<MedipostBusinessAssumptions value={business} onChange={setBusiness}/>:view==='analysis'?<MedipostDossierAnalysis/>:<MedipostBusinessPlan assumptions={business}/>} {/* Le compte unique rassemble réalisé et budget. */}
    {false && <>
    <div className="report-settings"><div><strong>Affichage du compte de résultat</strong><span>Activez les ratios de chaque rubrique par rapport au chiffre d’affaires.</span></div><div className="report-settings-actions"><Button variant={percentages ? 'primary' : 'secondary'} onClick={() => setPercentages(value => !value)} aria-pressed={percentages}>Pourcentage</Button></div></div>
    <Card className="profit-loss analysed-profit-loss">
      <div className="profit-loss-heading">
        <div><p className="eyebrow">Dossier analysé · comptes annuels BNB</p><h2>Compte de résultat détaillé</h2><p>2025 est provisoire. Cliquez sur une rubrique pour afficher les sous-rubriques disponibles dans les comptes annuels.</p></div>
        <div className="unit-note"><Sigma size={17}/><span>Montants en milliers d’euros</span></div>
      </div>
      <div className="report-table">
        <table className="report-matrix">
          <thead><tr><th>Rubrique</th><th>2023</th><th>2024</th><th>2025<br/><small>provisoire</small></th></tr></thead>
          <tbody>{report.map(line => <Fragment key={line.label}>
            <tr className={line.calculation ? 'calculation-row key-calculation' : 'account-section'}>
              <td>{line.details ? <button className="drilldown-button" onClick={() => toggle(line.label)} aria-expanded={open.has(line.label)}>{open.has(line.label) ? <ChevronDown size={17}/> : <ChevronRight size={17}/>}<span>{line.label}</span><small>{line.details.length} sous-rubrique{line.details.length > 1 ? 's' : ''}</small></button> : <span className="calculation-label"><Sigma size={15}/>{line.label}</span>}</td>
              {([2023, 2024, 2025] as Year[]).map(year => <td key={year}>{amount(line.values[year])}</td>)}
            </tr>
            {percentages && <tr className="percentage-row"><td>% du chiffre d’affaires</td>{([2023, 2024, 2025] as Year[]).map(year => <td key={year}>{percent(line.values[year], report[0].values[year])}</td>)}</tr>}
            {open.has(line.label) && line.details?.map(detail => <tr className="account-row" key={detail.code}>
              <td><em>{detail.code}</em>{detail.label}</td>
              {([2023, 2024, 2025] as Year[]).map(year => <td key={year}>{amount(detail.values[year])}</td>)}
            </tr>)}
          </Fragment>)}</tbody>
        </table>
      </div>
      <div className="analysis-source-note"><FileText size={16}/><span>2023 provient de l’export Medipost. Les sous-rubriques sont disponibles uniquement pour 2024 et 2025, selon le niveau de détail des comptes annuels BNB fournis.</span></div>
    </Card><MedipostCashFlow/><MedipostCashDetails/></>}
  </>;
}

